style.css:
@-moz-document domain("roblox.com") {
/* Fondo oscuro */
  body {
    background-color: #1e1e2f !important;
    color: #ffffff !important;
  }

  /* Oculta anuncios */
  .ads-container, .ad-container, .ad {
    display: none !important;
  }

  /* Personaliza el encabezado */
  .navbar, .header, .navigation {
    background-color: #2b2b3c !important;
    border-bottom: 1px solid #444 !important;
  }

  /* Estilo de botones */
  button, .btn {
    background-color: #3a3a5c !important;
    color: white !important;
    border: none !important;
  }

  button:hover, .btn:hover {
    background-color: #50507a !important;
  }

  /* Caja de búsqueda y entradas */
  input, textarea {
    background-color: #2e2e3f !important;
    color: #ffffff !important;
    border: 1px solid #555 !important;
  }

  /* Fondo del contenido principal */
  .container-main, .content {
    background-color: #2a2a3a !important;
    border-radius: 10px !important;
    padding: 15px !important;
  }
}
